        ];

        $agora = now();
        $linhas = [];
        $ignoradosPorColisao = 0;

        foreach ($itensTbca as $item) {
            $nome = $item['name'];

            if (isset($nomesCurados[$nome])) {
                $ignoradosPorColisao++;
                continue;
            }

            // Marca como usado já aqui — defende contra o mesmo nome
            // aparecer 2x dentro do próprio array da TBCA, o que faria o
            // upsert() falhar ("ON CONFLICT DO UPDATE command cannot affect
            // row a second time"). Já validamos 0 colisão interna na geração,
            // mas é barato garantir.
            $nomesCurados[$nome] = true;

            $linhas[] = [
                'name' => $item['name'],
                'protein_g' => $item['protein_g'],
                'carbohydrate_g' => $item['carbohydrate_g'],
                'fat_g' => $item['fat_g'],
                'calories_kcal' => $item['calories_kcal'],
                'serving_size_g' => $item['serving_size_g'],
                'source' => 'tbca',
                'created_at' => $agora,
                'updated_at' => $agora,
            ];
        }

        // Lotes de 500 — upsert() manda tudo numa query só por lote, em vez
        // de um round-trip por linha. ~5.000 linhas em ~10 queries no lugar
        // de ~5.000 queries individuais.
        $totalInseridos = 0;
        foreach (array_chunk($linhas, 500) as $lote) {
            DB::table('foods')->upsert(
                $lote,
                ['name'],
                ['protein_g', 'carbohydrate_g', 'fat_g', 'calories_kcal', 'serving_size_g', 'source', 'updated_at']
            );
            $totalInseridos += count($lote);
        }

        $this->command?->info("TBCA: {$totalInseridos} alimentos importados, {$ignoradosPorColisao} ignorados por colidir com um nome já curado.");
    }
